        while sum(degree_count) < n * d:
            u, v = random.sample(range(n), 2)
            if u == v or (u, v) in edges_added or (v, u) in edges_added:
                continue
            graph[u][v] = 1
            graph[v][u] = 1
            degree_count[u] += 1
            degree_count[v] += 1
            edges_added.add((u, v))

